    padding: 1rem 0;
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
    letter-spacing: 2px;
    text-transform: uppercase;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-weight: 500;
}

.header-actions {
    display: flex;
    gap: 1.5rem;
}

.header-actions button {
    font-size: 1.25rem;
    padding: 0.5rem;
}

/* Hero Section */
.hero {
    background-color: var(--surface-color);
    padding: 6rem 1rem;
    text-align: center;
    border-bottom: 1px solid var(--surface-hover);
}

.hero h1 {
    font-size: 3.5rem;
    margin-bottom: 1rem;
    font-weight: 800;
}

.hero p {
    font-size: 1.25rem;
    color: var(--secondary-text);
    margin-bottom: 2rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.btn-primary {
    display: inline-block;
    background-color: var(--primary-text);
    color: var(--bg-color);
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
    font-weight: 600;
    border-radius: 4px;
    transition: background-color 0.2s;
}

.btn-primary:hover {
    background-color: var(--secondary-text);
}

.btn-secondary {
    display: inline-block;
    background-color: transparent;
    color: var(--primary-text);
    border: 2px solid var(--primary-text);
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
    font-weight: 600;
    border-radius: 4px;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background-color: var(--primary-text);
    color: var(--bg-color);
}

