.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s;
}

.product-card:hover {
    transform: translateY(-5px);
}

.product-image {
    width: 100%;
    height: 300px;
    background-color: #2a2a2a;
    display: flex;
    align-items: center;
