    color: white;
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    font-weight: bold;
    border-radius: 4px;
}

.product-info {
    padding: 1.5rem;
}

.product-category {
    font-size: 0.875rem;
    color: var(--secondary-text);
    margin-bottom: 0.5rem;
}

.product-title {
    font-size: 1.125rem;
    margin-bottom: 0.5rem;
}

.product-price {
    font-weight: bold;
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.original-price {
    text-decoration: line-through;
    color: var(--secondary-text);
    font-size: 1rem;
    font-weight: normal;
    margin-right: 0.5rem;
}

.add-to-cart {
    width: 100%;
    background-color: var(--surface-hover);
    color: var(--primary-text);
    padding: 0.75rem;
    border-radius: 4px;
    font-weight: 600;
    transition: background-color 0.2s;
}

.add-to-cart:hover {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

/* Deals Section */
.deals-section {
    background-color: var(--surface-color);
}

.deals-banner {
    display: flex;
