    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
}

.deals-content h3 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
    color: var(--accent-color);
}

.deals-content p {
    font-size: 1.25rem;
    color: var(--secondary-text);
    margin-bottom: 2rem;
}

.deals-image {
    flex: 1;
    background-color: #222;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 400px;
}

.deals-image i {
    font-size: 8rem;
    color: #333;
}

